-- ==========================================================================
-- 🌍 SUPABASE POSTGRESQL / POSTGIS SEED SCRIPT FOR DIMA HASAO GRID (5,076 PTS)
-- Calibrated with authentic ISRIC SoilGrids measurements
-- ==========================================================================

CREATE EXTENSION IF NOT EXISTS postgis;

-- Create table if not exists
CREATE TABLE IF NOT EXISTS grid_points (
    id BIGSERIAL PRIMARY KEY,
    district VARCHAR(100) NOT NULL DEFAULT 'Dima Hasao',
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    elevation DOUBLE PRECISION,
    slope DOUBLE PRECISION NOT NULL,
    clay_percent DOUBLE PRECISION NOT NULL,
    sand_percent DOUBLE PRECISION DEFAULT 35.0,
    silt_percent DOUBLE PRECISION DEFAULT 30.0,
    bulk_density DOUBLE PRECISION DEFAULT 1.15,
    aspect DOUBLE PRECISION DEFAULT 0.0,
    aspect_sin DOUBLE PRECISION DEFAULT 0.0,
    aspect_cos DOUBLE PRECISION DEFAULT 1.0,
    shear_stress_factor DOUBLE PRECISION DEFAULT 0.1,
    rain_day1 DOUBLE PRECISION DEFAULT 0.0,
    rain_day2 DOUBLE PRECISION DEFAULT 0.0,
    rain_day3 DOUBLE PRECISION DEFAULT 0.0,
    probability DOUBLE PRECISION DEFAULT 0.0,
    risk_level VARCHAR(50) DEFAULT 'LOW',
    geom GEOMETRY(Point, 4326),
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_grid_points_lat_lon ON grid_points(latitude, longitude);
CREATE INDEX IF NOT EXISTS idx_grid_points_geom ON grid_points USING GIST (geom);

-- Clear existing records
TRUNCATE TABLE grid_points RESTART IDENTITY CASCADE;

